 "content": "def transform(grid):
    """Stamp the input's zero-cell pattern at every nonzero input cell."""
    h, w = len(grid), len(grid[0])
    zero_offsets = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0]
    out = [[0 for _ in range(w * w)] for _ in range(h * h)]
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 0:
                for dr, dc in zero_offsets:
                    out[r * h + dr][c * w + dc] = value
    return out
